insert into public.courses(code,title,description,status,slug,short_description,full_description,category,difficulty,lesson_count,estimated_minutes,published,skill_tags)
values('BPO-001','Customer Support & BPO Career Readiness','Prepare for voice, non-voice, customer support and entry-level operations roles through practical communication and customer-handling work.','active','customer-support-bpo-career-readiness','Prepare for voice, non-voice, customer support and entry-level operations roles through practical communication and customer-handling work.','Prepare for voice, non-voice, customer support and entry-level operations roles through practical communication and customer-handling work. Demonstrate clear workplace English, structured customer handling, accurate written support and confident role-specific interview performance through realistic practice.','Career Readiness','Beginner to interview-ready',37,1680,true,array['Workplace English','Customer Service','Spoken Communication','Active Listening','Problem Solving','Voice Support','Chat Support','Email Support','Interview Readiness']::text[])
