select topic.id,'Spoken Communication: Core Concepts','customer-support-bpo-career-readiness-spoken-communication-core-concepts',1,true from public.course_topics topic join public.course_modules module on module.id=topic.module_id join public.courses course on course.id=module.course_id where course.code='BPO-001' and module.title='Module 3 · Spoken Communication' and topic.title='Understand'
