update public.taksh_content_assets set title='Customer Service Fundamentals: Core Concepts',slug='customer-support-bpo-career-readiness-customer-service-fundamentals-core-concepts',difficulty='Foundation to applied',status='published',content='{"identity":{"course":"Customer Support & BPO Career Readiness","module":"Module 5 · Customer Service Fundamentals","topic":"Understand","subtopic":"Customer Service Fundamentals: Core Concepts","title":"Customer Service Fundamentals: Core Concepts","slug":"customer-support-bpo-career-readiness-customer-service-fundamentals-core-concepts","target_audience":"College students, fresh graduates and entry-level job seekers","difficulty":"Foundation to applied","explanation_depth":"Concept, platform workflow and guided lab","exam_context":"Customer Support & BPO Career Readiness module assessment and entry-level interview preparation"},"learning_design":{"learning_objectives":[{"objective_id":"understand","objective":"Explain customer service fundamentals: core concepts with confidence.","skill_level":"understand"},{"objective_id":"apply","objective":"Practise this workflow: Acknowledge impact, clarify the goal, explain what you can do, act or escalate, give a truthful timeline and confirm closure.","skill_level":"apply"}],"prerequisites":[],"estimated_learning_minutes":22},"core_content":{"introduction":"Build practical capability in customer service fundamentals: core concepts through platform concepts, a guided workflow and a hands-on task.","canonical_definition":"Good service combines acknowledgement, accurate diagnosis, appropriate ownership, realistic expectations and a complete resolution or controlled handoff.","why_it_matters":"Customer Service Fundamentals is used in entry-level work and is assessed through practical scenarios and interviews.","concept_explanation":"Principle: Good service combines acknowledgement, accurate diagnosis, appropriate ownership, realistic expectations and a complete resolution or controlled ha